'use strict';

const QUOTE = 0x22;
const CR = 0x0d;
const LF = 0x0a;
const SPACE = 0x20;
const BOM = 0xfeff;

// Parser states.
const FIELD_START = 0;
const UNQUOTED = 1;
const QUOTED = 2;
// Just read a `"` inside a quoted field: it either closes the field or is the
// first half of an escaped `""`.
const QUOTE_IN_QUOTED = 3;

class CsvError extends Error {
  /**
   * @param {string} message
   * @param {number} line 1-based line of the problem.
   * @param {number} column 1-based column, in UTF-16 code units.
   */
  constructor(message, line, column) {
    super(`${message} (line ${line}, column ${column})`);
    this.name = 'CsvError';
    this.line = line;
    this.column = column;
  }
}

function describe(value) {
  if (value === null) return 'null';
  if (typeof value === 'string') return JSON.stringify(value);
  if (Array.isArray(value)) return 'array';
  return typeof value;
}

function checkOptionsObject(options) {
  if (options === null || typeof options !== 'object') {
    throw new TypeError(`options must be an object; received ${describe(options)}`);
  }
}

function readDelimiter(delimiter) {
  if (delimiter === undefined) return ',';
  if (
    typeof delimiter !== 'string' ||
    delimiter.length !== 1 ||
    delimiter === '"' ||
    delimiter === '\r' ||
    delimiter === '\n'
  ) {
    throw new TypeError(
      `delimiter must be a single character other than '"', CR or LF; received ${describe(delimiter)}`,
    );
  }
  return delimiter;
}

function readBoolean(options, name) {
  const value = options[name];
  if (value === undefined) return false;
  if (typeof value !== 'boolean') {
    throw new TypeError(`${name} must be a boolean; received ${describe(value)}`);
  }
  return value;
}

function readParseOptions(options) {
  checkOptionsObject(options);
  return {
    delimiter: readDelimiter(options.delimiter),
    header: readBoolean(options, 'header'),
    skipEmptyLines: readBoolean(options, 'skipEmptyLines'),
  };
}

function toObject(names, values) {
  const record = {};
  for (let i = 0; i < names.length; i++) {
    if (names[i] === '__proto__') {
      // Plain assignment would call the prototype setter and drop the value.
      Object.defineProperty(record, '__proto__', {
        value: values[i],
        enumerable: true,
        writable: true,
        configurable: true,
      });
    } else {
      record[names[i]] = values[i];
    }
  }
  return record;
}

/**
 * Incremental state machine behind both parse() and createParser(). It reads
 * every character exactly once and keeps only the record in progress, so work
 * and memory are linear in the input no matter how it is chunked.
 */
class Parser {
  constructor({ delimiter, header, skipEmptyLines }) {
    this.delimiter = delimiter.charCodeAt(0);
    this.header = header;
    this.skipEmptyLines = skipEmptyLines;

    this.state = FIELD_START;
    this.started = false; // whether a non-empty chunk has arrived (BOM check)
    this.offset = 0; // absolute offset of the next chunk, BOM excluded
    this.line = 1;
    this.lineStart = 0; // absolute offset of the current line's first character
    this.prevCR = false;

    this.fields = []; // completed fields of the record in progress
    this.parts = []; // pieces of the field in progress
    this.recordStarted = false; // the record in progress has consumed a character
    this.recordLine = 1;
    this.fieldLine = 1; // where the field in progress starts
    this.fieldColumn = 1;

    this.names = null; // header row, once read
    this.seenNames = header ? new Set() : null; // only while reading the header row
  }

  write(chunk) {
    if (!this.started) {
      if (chunk.length === 0) return [];
      this.started = true;
      if (chunk.charCodeAt(0) === BOM) chunk = chunk.slice(1);
    }

    const out = [];
    const base = this.offset;
    const delimiter = this.delimiter;
    const n = chunk.length;
    let segmentStart = 0; // start of the unflushed field text in this chunk

    for (let i = 0; i < n; i++) {
      const c = chunk.charCodeAt(i);

      switch (this.state) {
        case FIELD_START:
          if (c === LF && this.prevCR) break; // rest of a CRLF that already ended the record
          if (!this.recordStarted) this.recordLine = this.line;
          this.fieldLine = this.line;
          this.fieldColumn = base + i - this.lineStart + 1;
          if (c === QUOTE) {
            this.recordStarted = true;
            this.state = QUOTED;
            segmentStart = i + 1;
          } else if (c === delimiter) {
            this.recordStarted = true;
            this.pushField('');
          } else if (c === CR || c === LF) {
            if (this.recordStarted || !this.skipEmptyLines) {
              this.pushField('');
              this.endRecord(out);
            }
          } else {
            this.recordStarted = true;
            this.state = UNQUOTED;
            segmentStart = i;
          }
          break;

        case UNQUOTED:
          if (c === delimiter || c === CR || c === LF) {
            this.parts.push(chunk.slice(segmentStart, i));
            this.pushField(this.takeField());
            this.state = FIELD_START;
            if (c !== delimiter) this.endRecord(out);
          }
          break;

        case QUOTED:
          if (c === QUOTE) {
            this.parts.push(chunk.slice(segmentStart, i));
            this.state = QUOTE_IN_QUOTED;
          }
          break;

        case QUOTE_IN_QUOTED:
          if (c === QUOTE) {
            // Escaped quote: the second `"` starts the next piece, so it is kept once.
            segmentStart = i;
            this.state = QUOTED;
          } else if (c === delimiter || c === CR || c === LF) {
            this.pushField(this.takeField());
            this.state = FIELD_START;
            if (c !== delimiter) this.endRecord(out);
          } else {
            throw new CsvError(
              'Unexpected character after closing quote',
              this.line,
              base + i - this.lineStart + 1,
            );
          }
          break;
      }

      // Line numbers follow every line break, including those inside quoted fields.
      if (c === CR) {
        this.line++;
        this.lineStart = base + i + 1;
        this.prevCR = true;
      } else {
        if (c === LF) {
          if (!this.prevCR) this.line++;
          this.lineStart = base + i + 1;
        }
        this.prevCR = false;
      }
    }

    if ((this.state === UNQUOTED || this.state === QUOTED) && segmentStart < n) {
      this.parts.push(chunk.slice(segmentStart));
    }
    this.offset = base + n;
    return out;
  }

  end() {
    const out = [];
    switch (this.state) {
      case QUOTED:
        throw new CsvError('Unclosed quoted field', this.fieldLine, this.fieldColumn);
      case UNQUOTED:
      case QUOTE_IN_QUOTED:
        this.pushField(this.takeField());
        this.endRecord(out);
        break;
      case FIELD_START:
        // Only a trailing delimiter leaves a started record here; a trailing
        // line break has already ended its record and starts no new one.
        if (this.recordStarted) {
          this.fieldLine = this.line;
          this.fieldColumn = this.offset - this.lineStart + 1;
          this.pushField('');
          this.endRecord(out);
        }
        break;
    }
    return out;
  }

  takeField() {
    const parts = this.parts;
    const value = parts.length === 1 ? parts[0] : parts.join('');
    parts.length = 0;
    return value;
  }

  pushField(value) {
    if (this.seenNames !== null) {
      if (this.seenNames.has(value)) {
        throw new CsvError(
          `Duplicate header name ${JSON.stringify(value)}`,
          this.fieldLine,
          this.fieldColumn,
        );
      }
      this.seenNames.add(value);
    }
    this.fields.push(value);
  }

  endRecord(out) {
    const fields = this.fields;
    this.fields = [];
    this.recordStarted = false;

    if (!this.header) {
      out.push(fields);
    } else if (this.names === null) {
      this.names = fields;
      this.seenNames = null;
    } else if (fields.length !== this.names.length) {
      throw new CsvError(
        `Expected ${this.names.length} fields to match the header but found ${fields.length}`,
        this.recordLine,
        1,
      );
    } else {
      out.push(toObject(this.names, fields));
    }
  }
}

/**
 * Parses a complete CSV string.
 *
 * @param {string} text
 * @param {{delimiter?: string, header?: boolean, skipEmptyLines?: boolean}} [options]
 * @returns {Array<string[]> | Array<Record<string, string>>} arrays of fields,
 *   or objects keyed by the first record when `header` is true.
 * @throws {TypeError} when `text` is not a string or an option is invalid.
 * @throws {CsvError} when the input is malformed.
 */
function parse(text, options = {}) {
  if (typeof text !== 'string') {
    throw new TypeError(`text must be a string; received ${describe(text)}`);
  }
  const parser = new Parser(readParseOptions(options));
  const records = parser.write(text);
  for (const record of parser.end()) records.push(record);
