'use strict';

const { describe, it } = require('node:test');
const assert = require('node:assert/strict');
const { parse, CsvError } = require('../src/csv.js');

function assertCsvError(fn, line, column) {
  assert.throws(fn, (err) => {
    assert.ok(err instanceof CsvError, `expected a CsvError, got ${err}`);
    assert.deepEqual({ line: err.line, column: err.column }, { line, column });
    return true;
  });
}

describe('parse: arguments', () => {
  it('rejects non-string text with TypeError', () => {
    for (const text of [undefined, null, 42, ['a'], Buffer.from('a')]) {
      assert.throws(() => parse(text), TypeError);
    }
  });

  it('rejects invalid delimiters with TypeError', () => {
    for (const delimiter of ['', ';;', '"', '\r', '\n', null, 44, '😀']) {
      assert.throws(() => parse('a', { delimiter }), TypeError, `delimiter ${String(delimiter)}`);
    }
  });

  it('rejects non-object options and non-boolean flags with TypeError', () => {
    assert.throws(() => parse('a', null), TypeError);
    assert.throws(() => parse('a', 'x'), TypeError);
    assert.throws(() => parse('a', { header: 'yes' }), TypeError);
    assert.throws(() => parse('a', { skipEmptyLines: 1 }), TypeError);
  });

  it('ignores options it does not know, such as stringify eol', () => {
    assert.deepEqual(parse('a\n', { eol: '\n' }), [['a']]);
  });
});

describe('parse: records and fields', () => {
  it('returns [] for an empty string', () => {
    assert.deepEqual(parse(''), []);
  });

  it('splits fields on commas', () => {
    assert.deepEqual(parse('a,b,c'), [['a', 'b', 'c']]);
  });

  it('keeps empty fields, including after a trailing delimiter', () => {
    assert.deepEqual(parse(',a,,'), [['', 'a', '', '']]);
    assert.deepEqual(parse(','), [['', '']]);
  });

  it('splits records on CRLF, LF and CR mixed in one input', () => {
    assert.deepEqual(parse('a\r\nb\nc\rd'), [['a'], ['b'], ['c'], ['d']]);
  });

  it('does not start a record after one final line break', () => {
    assert.deepEqual(parse('a\n'), [['a']]);
    assert.deepEqual(parse('a\r\n'), [['a']]);
    assert.deepEqual(parse('a\r'), [['a']]);
  });

  it('turns every other empty line into a record with one empty field', () => {
    assert.deepEqual(parse('\n'), [['']]);
    assert.deepEqual(parse('a\n\nb'), [['a'], [''], ['b']]);
    assert.deepEqual(parse('a\n\n'), [['a'], ['']]);
    assert.deepEqual(parse('\r\n\r\n'), [[''], ['']]);
  });

  it('treats CR CR and LF CR as two line breaks, CRLF as one', () => {
    assert.deepEqual(parse('a\r\rb'), [['a'], [''], ['b']]);
    assert.deepEqual(parse('a\n\rb'), [['a'], [''], ['b']]);
    assert.deepEqual(parse('a\r\n\r\nb'), [['a'], [''], ['b']]);
  });

  it('never trims whitespace', () => {
    assert.deepEqual(parse(' a , b \t'), [[' a ', ' b \t']]);
    assert.deepEqual(parse('  \n'), [['  ']]);
  });

  it('treats a quote inside an unquoted field as an ordinary character', () => {
    assert.deepEqual(parse('a"b,c"'), [['a"b', 'c"']]);
    assert.deepEqual(parse(' "a"'), [[' "a"']]);
  });

  it('uses a custom delimiter and treats commas as text', () => {
    assert.deepEqual(parse('a;b,c\n1;2', { delimiter: ';' }), [['a', 'b,c'], ['1', '2']]);
    assert.deepEqual(parse('a\tb', { delimiter: '\t' }), [['a', 'b']]);
    assert.deepEqual(parse('é§ü', { delimiter: '§' }), [['é', 'ü']]);
  });

  it('keeps non-ASCII text intact', () => {
    assert.deepEqual(parse('é,😀,中文\n"👍🏽,x"'), [['é', '😀', '中文'], ['👍🏽,x']]);
  });
});

describe('parse: byte order mark', () => {
  it('ignores a leading BOM', () => {
    assert.deepEqual(parse('﻿a,b'), [['a', 'b']]);
    assert.deepEqual(parse('﻿'), []);
    assert.deepEqual(parse('﻿"a"'), [['a']]);
  });

  it('keeps a BOM that is not the first character', () => {
    assert.deepEqual(parse('﻿﻿a'), [['﻿a']]);
    assert.deepEqual(parse('a\n﻿b'), [['a'], ['﻿b']]);
  });
});

describe('parse: quoted fields', () => {
  it('keeps delimiters and line breaks inside quotes literally', () => {
    assert.deepEqual(parse('"a,b","c\r\nd","e\rf\ng"'), [['a,b', 'c\r\nd', 'e\rf\ng']]);
  });

  it('turns "" into one literal quote', () => {
