'use strict';

const { describe, it } = require('node:test');
const assert = require('node:assert/strict');
const { parse, createParser, CsvError } = require('../src/csv.js');

// Mulberry32: a small seeded PRNG so random cases are reproducible.
function random(seed) {
  let state = seed >>> 0;
  return () => {
    state = (state + 0x6d2b79f5) >>> 0;
    let t = state;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

// Records or the CsvError position, so parse and the stream compare directly.
function outcome(fn) {
  try {
    return { records: fn() };
  } catch (err) {
    if (!(err instanceof CsvError)) throw err;
    return { error: { line: err.line, column: err.column, message: err.message } };
  }
}

function parseWhole(text, options) {
  return outcome(() => parse(text, options));
}

function parseChunks(chunks, options) {
  const parser = createParser(options);
  return outcome(() => {
    const records = [];
    for (const chunk of chunks) records.push(...parser.write(chunk));
    records.push(...parser.end());
    return records;
  });
}

function splitAt(text, cuts) {
  const chunks = [];
  let from = 0;
  for (const cut of cuts) {
    chunks.push(text.slice(from, cut));
    from = cut;
  }
  chunks.push(text.slice(from));
  return chunks;
}

const OPTION_SETS = [
  {},
  { skipEmptyLines: true },
  { header: true },
  { header: true, skipEmptyLines: true },
  { delimiter: ';' },
];

// Inputs chosen to put every state transition next to a possible chunk boundary.
const CORPUS = [
  '',
  '﻿',
  '﻿a,b\r\nc,d',
  'a,b\r\nc,d\r\n',
  'a\r\rb\n\rc\r\n\r\n',
  '"a""b",c\r\n"d\r\ne",""\n""""',
  '\n\n,\n"",x\n',
  'h1,h2\r\n1,2\r\n\r\n3,4\r',
  'h1;h2\n"1;x";2\n',
  'a,a\nb',
  'a,b\n1,2,3',
  'a,b\n"x\r\ny",1\n2',
  '"a"b',
  'a,"b\r\nc',
  '😀,"é"""\n中,x',
];

function assertSameAsParse(text, chunks, options) {
  assert.deepEqual(
    parseChunks(chunks, options),
    parseWhole(text, options),
    `chunks ${JSON.stringify(chunks)} with options ${JSON.stringify(options)}`,
  );
}

describe('createParser: arguments and lifecycle', () => {
  it('validates options like parse', () => {
    assert.throws(() => createParser({ delimiter: '"' }), TypeError);
    assert.throws(() => createParser(null), TypeError);
    assert.throws(() => createParser({ header: 1 }), TypeError);
  });

  it('rejects a non-string chunk with TypeError, then refuses further calls', () => {
    const parser = createParser();
    assert.throws(() => parser.write(Buffer.from('a')), TypeError);
    assert.throws(() => parser.write('a'), (err) => err instanceof Error && !(err instanceof TypeError));
    assert.throws(() => parser.end(), Error);
  });

  it('refuses both methods after end()', () => {
    const parser = createParser();
    parser.write('a');
    assert.deepEqual(parser.end(), [['a']]);
    assert.throws(() => parser.write('b'), Error);
    assert.throws(() => parser.end(), Error);
  });

  it('refuses both methods after write() throws a CsvError', () => {
    const parser = createParser();
    assert.throws(() => parser.write('"a"x'), CsvError);
    assert.throws(() => parser.write('b'), (err) => !(err instanceof CsvError));
    assert.throws(() => parser.end(), Error);
  });

  it('refuses both methods after end() throws a CsvError', () => {
    const parser = createParser();
    parser.write('"open');
    assert.throws(() => parser.end(), CsvError);
    assert.throws(() => parser.end(), (err) => !(err instanceof CsvError));
    assert.throws(() => parser.write(''), Error);
  });

  it('keeps separate state per parser', () => {
    const first = createParser();
    const second = createParser({ delimiter: ';' });
    first.write('"a,');
    second.write('b;c');
    assert.deepEqual(second.end(), [['b', 'c']]);
    assert.deepEqual(first.write('b"\n'), [['a,b']]);
  });
});

describe('createParser: when records are returned', () => {
  it('returns a record from the write whose chunk holds its ending line break', () => {
    const parser = createParser();
    assert.deepEqual(parser.write('a,b'), []);
    assert.deepEqual(parser.write('\nc'), [['a', 'b']]);
    assert.deepEqual(parser.write(',d\r\ne\n'), [['c', 'd'], ['e']]);
    assert.deepEqual(parser.end(), []);
  });

  it('returns a record at a chunk-final CR without an empty record for the LF', () => {
    const parser = createParser();
    assert.deepEqual(parser.write('a\r'), [['a']]);
    assert.deepEqual(parser.write('\nb'), []);
    assert.deepEqual(parser.end(), [['b']]);
  });

  it('holds a quoted line break until the field closes', () => {
    const parser = createParser();
    assert.deepEqual(parser.write('"a\n'), []);
    assert.deepEqual(parser.write('b"\n'), [['a\nb']]);
    assert.deepEqual(parser.end(), []);
  });

  it('does not return the header row in header mode', () => {
    const parser = createParser({ header: true });
    assert.deepEqual(parser.write('x,y\n'), []);
    assert.deepEqual(parser.write('1,2\n3,'), [{ x: '1', y: '2' }]);
    assert.deepEqual(parser.end(), [{ x: '3', y: '' }]);
  });

  it('strips a BOM that arrives after empty chunks', () => {
    const parser = createParser();
    parser.write('');
    assert.deepEqual(parser.write('﻿a\n'), [['a']]);
    assert.deepEqual(parser.write('﻿b'), []);
    assert.deepEqual(parser.end(), [['﻿b']]);
  });
});

describe('createParser: matches parse wherever the input is split', () => {
  it('matches for every single split point', () => {
    for (const text of CORPUS) {
      for (const options of OPTION_SETS) {
        for (let cut = 0; cut <= text.length; cut++) {
          assertSameAsParse(text, splitAt(text, [cut]), options);
        }
      }
    }
  });

  it('matches when fed one code unit at a time, with empty chunks between', () => {
    for (const text of CORPUS) {
      for (const options of OPTION_SETS) {
        const units = text.split('').flatMap((unit) => [unit, '']);
        assertSameAsParse(text, units, options);
      }
    }
  });

  it('matches for seeded random inputs and random chunking', () => {
    const next = random(0xc5f);
    const alphabet = ['a', 'b', ',', ';', '"', '"', '\r', '\n', ' ', '﻿', 'é'];
    for (let run = 0; run < 3000; run++) {
      const length = Math.floor(next() * 24);
      let text = '';
      for (let i = 0; i < length; i++) text += alphabet[Math.floor(next() * alphabet.length)];
      const cuts = [];
      for (let i = 1; i < text.length; i++) if (next() < 0.3) cuts.push(i);
      const options = OPTION_SETS[run % OPTION_SETS.length];
      assertSameAsParse(text, splitAt(text, cuts), options);
    }
  });
});

describe('createParser: cost stays linear in the input', () => {
  // Re-reading buffered input on each write would make this quadratic:
  // around 10^10 steps, far past the timeout.
  it('handles 200k one-character writes inside one quoted field', { timeout: 10000 }, () => {
    const size = 200000;
    const parser = createParser();
    parser.write('"');
    for (let i = 0; i < size; i++) assert.deepEqual(parser.write(i % 2 ? '"' : '"'), []);
    parser.write('"\n');
    // 200k quotes are 100k escaped pairs, then one closing quote.
    const records = parser.end();
    assert.deepEqual(records, []);
  });

  it('streams 100k records one character at a time', { timeout: 10000 }, () => {
    const text = 'ab,"c""d"\r\n'.repeat(100000);
    const parser = createParser();
    let count = 0;
    for (let i = 0; i < text.length; i++) count += parser.write(text[i]).length;
    count += parser.end().length;
    assert.equal(count, 100000);
  });
});

