'use strict';

const QUOTE = 0x22;
const CR = 0x0d;
const LF = 0x0a;
const SPACE = 0x20;
const BOM = 0xfeff;

// Parser states.
const FIELD_START = 0;
const UNQUOTED = 1;
const QUOTED = 2;
// Just read a `"` inside a quoted field: it either closes the field or is the
// first half of an escaped `""`.
const QUOTE_IN_QUOTED = 3;

class CsvError extends Error {
  /**
   * @param {string} message
   * @param {number} line 1-based line of the problem.
   * @param {number} column 1-based column, in UTF-16 code units.
   */
  constructor(message, line, column) {
    super(`${message} (line ${line}, column ${column})`);
    this.name = 'CsvError';
    this.line = line;
    this.column = column;
  }
}

function describe(value) {
  if (value === null) return 'null';
  if (typeof value === 'string') return JSON.stringify(value);
  if (Array.isArray(value)) return 'array';
  return typeof value;
}

function checkOptionsObject(options) {
  if (options === null || typeof options !== 'object') {
    throw new TypeError(`options must be an object; received ${describe(options)}`);
  }
}

function readDelimiter(delimiter) {
  if (delimiter === undefined) return ',';
  if (
    typeof delimiter !== 'string' ||
    delimiter.length !== 1 ||
    delimiter === '"' ||
    delimiter === '\r' ||
    delimiter === '\n'
  ) {
    throw new TypeError(
      `delimiter must be a single character other than '"', CR or LF; received ${describe(delimiter)}`,
    );
  }
  return delimiter;
}

function readBoolean(options, name) {
  const value = options[name];
  if (value === undefined) return false;
  if (typeof value !== 'boolean') {
    throw new TypeError(`${name} must be a boolean; received ${describe(value)}`);
  }
  return value;
}

function readParseOptions(options) {
  checkOptionsObject(options);
  return {
    delimiter: readDelimiter(options.delimiter),
    header: readBoolean(options, 'header'),
    skipEmptyLines: readBoolean(options, 'skipEmptyLines'),
  };
}

function toObject(names, values) {
  const record = {};
  for (let i = 0; i < names.length; i++) {
    if (names[i] === '__proto__') {
      // Plain assignment would call the prototype setter and drop the value.
      Object.defineProperty(record, '__proto__', {
        value: values[i],
        enumerable: true,
        writable: true,
        configurable: true,
      });
    } else {
      record[names[i]] = values[i];
    }
  }
  return record;
}

/**
 * Incremental state machine behind both parse() and createParser(). It reads
 * every character exactly once and keeps only the record in progress, so work
 * and memory are linear in the input no matter how it is chunked.
 */
class Parser {
  constructor({ delimiter, header, skipEmptyLines }) {
    this.delimiter = delimiter.charCodeAt(0);
    this.header = header;
    this.skipEmptyLines = skipEmptyLines;

    this.state = FIELD_START;
    this.started = false; // whether a non-empty chunk has arrived (BOM check)
    this.offset = 0; // absolute offset of the next chunk, BOM excluded
    this.line = 1;
    this.lineStart = 0; // absolute offset of the current line's first character
    this.prevCR = false;

    this.fields = []; // completed fields of the record in progress
    this.parts = []; // pieces of the field in progress
    this.recordStarted = false; // the record in progress has consumed a character
    this.recordLine = 1;
    this.fieldLine = 1; // where the field in progress starts
    this.fieldColumn = 1;

    this.names = null; // header row, once read
    this.seenNames = header ? new Set() : null; // only while reading the header row
  }

  write(chunk) {
    if (!this.started) {
      if (chunk.length === 0) return [];
      this.started = true;
      if (chunk.charCodeAt(0) === BOM) chunk = chunk.slice(1);
    }

    const out = [];
    const base = this.offset;
    const delimiter = this.delimiter;
    const n = chunk.length;
    let segmentStart = 0; // start of the unflushed field text in this chunk

    for (let i = 0; i < n; i++) {
      const c = chunk.charCodeAt(i);

      switch (this.state) {
        case FIELD_START:
          if (c === LF && this.prevCR) break; // rest of a CRLF that already ended the record
          if (!this.recordStarted) this.recordLine = this.line;
          this.fieldLine = this.line;
          this.fieldColumn = base + i - this.lineStart + 1;
          if (c === QUOTE) {
            this.recordStarted = true;
            this.state = QUOTED;
            segmentStart = i + 1;
          } else if (c === delimiter) {
            this.recordStarted = true;
            this.pushField('');
          } else if (c === CR || c === LF) {
            if (this.recordStarted || !this.skipEmptyLines) {
              this.pushField('');
              this.endRecord(out);
            }
          } else {
            this.recordStarted = true;
            this.state = UNQUOTED;
            segmentStart = i;
          }
          break;

        case UNQUOTED:
          if (c === delimiter || c === CR || c === LF) {
            this.parts.push(chunk.slice(segmentStart, i));
            this.pushField(this.takeField());
            this.state = FIELD_START;
            if (c !== delimiter) this.endRecord(out);
          }
          break;

        case QUOTED:
          if (c === QUOTE) {
            this.parts.push(chunk.slice(segmentStart, i));
            this.state = QUOTE_IN_QUOTED;
          }
          break;

        case QUOTE_IN_QUOTED:
          if (c === QUOTE) {
            // Escaped quote: the second `"` starts the next piece, so it is kept once.
            segmentStart = i;
            this.state = QUOTED;
          } else if (c === delimiter || c === CR || c === LF) {
            this.pushField(this.takeField());
            this.state = FIELD_START;
            if (c !== delimiter) this.endRecord(out);
          } else {
            throw new CsvError(
              'Unexpected character after closing quote',
              this.line,
              base + i - this.lineStart + 1,
            );
          }
          break;
      }

      // Line numbers follow every line break, including those inside quoted fields.
      if (c === CR) {
        this.line++;
        this.lineStart = base + i + 1;
        this.prevCR = true;
      } else {
        if (c === LF) {
          if (!this.prevCR) this.line++;
          this.lineStart = base + i + 1;
        }
        this.prevCR = false;
      }
    }

    if ((this.state === UNQUOTED || this.state === QUOTED) && segmentStart < n) {
      this.parts.push(chunk.slice(segmentStart));
    }
    this.offset = base + n;
    return out;
  }

  end() {
    const out = [];
    switch (this.state) {
      case QUOTED:
        throw new CsvError('Unclosed quoted field', this.fieldLine, this.fieldColumn);
      case UNQUOTED:
      case QUOTE_IN_QUOTED:
        this.pushField(this.takeField());
        this.endRecord(out);
        break;
      case FIELD_START:
        // Only a trailing delimiter leaves a started record here; a trailing
        // line break has already ended its record and starts no new one.
        if (this.recordStarted) {
          this.fieldLine = this.line;
          this.fieldColumn = this.offset - this.lineStart + 1;
          this.pushField('');
          this.endRecord(out);
        }
        break;
    }
    return out;
  }

  takeField() {
    const parts = this.parts;
    const value = parts.length === 1 ? parts[0] : parts.join('');
    parts.length = 0;
    return value;
  }

  pushField(value) {
    if (this.seenNames !== null) {
      if (this.seenNames.has(value)) {
        throw new CsvError(
          `Duplicate header name ${JSON.stringify(value)}`,
          this.fieldLine,
          this.fieldColumn,
        );
      }
      this.seenNames.add(value);
    }
    this.fields.push(value);
  }

  endRecord(out) {
    const fields = this.fields;
    this.fields = [];
    this.recordStarted = false;

    if (!this.header) {
      out.push(fields);
    } else if (this.names === null) {
      this.names = fields;
      this.seenNames = null;
    } else if (fields.length !== this.names.length) {
      throw new CsvError(
        `Expected ${this.names.length} fields to match the header but found ${fields.length}`,
        this.recordLine,
        1,
      );
    } else {
      out.push(toObject(this.names, fields));
    }
  }
}

/**
 * Parses a complete CSV string.
 *
 * @param {string} text
 * @param {{delimiter?: string, header?: boolean, skipEmptyLines?: boolean}} [options]
 * @returns {Array<string[]> | Array<Record<string, string>>} arrays of fields,
 *   or objects keyed by the first record when `header` is true.
 * @throws {TypeError} when `text` is not a string or an option is invalid.
 * @throws {CsvError} when the input is malformed.
 */
function parse(text, options = {}) {
  if (typeof text !== 'string') {
    throw new TypeError(`text must be a string; received ${describe(text)}`);
  }
  const parser = new Parser(readParseOptions(options));
  const records = parser.write(text);
  for (const record of parser.end()) records.push(record);
  return records;
}

/**
 * Creates a parser for input that arrives in pieces. Chunks may split the
 * input anywhere; the combined output and errors match parse() on the whole.
 * Once end() has run or either method has thrown, both methods throw.
 *
 * @param {{delimiter?: string, header?: boolean, skipEmptyLines?: boolean}} [options]
 * @returns {{write(chunk: string): Array, end(): Array}}
 */
function createParser(options = {}) {
  const parser = new Parser(readParseOptions(options));
  let finished = false;

  function run(step) {
    if (finished) {
      throw new Error('CSV parser is finished: end() was called or an earlier call threw');
    }
    try {
      return step();
    } catch (err) {
      finished = true;
      throw err;
    }
  }

  return {
    write(chunk) {
      return run(() => {
        if (typeof chunk !== 'string') {
          throw new TypeError(`chunk must be a string; received ${describe(chunk)}`);
        }
        return parser.write(chunk);
      });
    },
    end() {
      const records = run(() => parser.end());
      finished = true;
      return records;
    },
  };
}

function readStringifyOptions(options) {
  checkOptionsObject(options);
  const delimiter = readDelimiter(options.delimiter);

  let eol = options.eol;
  if (eol === undefined) {
    eol = '\r\n';
  } else if (eol !== '\r\n' && eol !== '\n') {
    throw new TypeError(`eol must be '\\r\\n' or '\\n'; received ${describe(eol)}`);
  }

  let header = options.header;
  if (header === undefined || header === false) {
    header = null;
  } else if (!Array.isArray(header) || !header.every((name) => typeof name === 'string')) {
    throw new TypeError('header must be an array of column name strings');
  }

  return { delimiter, eol, header };
}

function toText(value, where) {
  if (typeof value === 'string') return value;
  if (typeof value === 'number' || typeof value === 'boolean') return String(value);
  if (value === null || value === undefined) return '';
  throw new TypeError(
    `${where}: expected a string, number, boolean, null or undefined; received ${describe(value)}`,
  );
}

function needsQuotes(text, delimiter) {
  const last = text.length - 1;
  if (last < 0) return false;
  if (text.charCodeAt(0) === SPACE || text.charCodeAt(last) === SPACE) return true;
  for (let i = 0; i <= last; i++) {
    const c = text.charCodeAt(i);
    if (c === delimiter || c === QUOTE || c === CR || c === LF) return true;
  }
  return false;
}

function encodeRecord(values, delimiter, where, isFirst) {
  const delimiterCode = delimiter.charCodeAt(0);
  const encoded = new Array(values.length);
  for (let i = 0; i < values.length; i++) {
    const text = toText(values[i], `${where}, field ${i}`);
    encoded[i] = needsQuotes(text, delimiterCode) ? `"${text.replace(/"/g, '""')}"` : text;
  }
  // An unquoted lone empty field would be an empty line, which skipEmptyLines drops.
  if (encoded.length === 1 && encoded[0] === '') return '""';

  const line = encoded.join(delimiter);
  // parse() drops a leading BOM, so the output must not start with a bare one.
  // The first field is unquoted here, so wrapping it needs no escaping.
  if (isFirst && line.charCodeAt(0) === BOM) {
    return `"${encoded[0]}"${line.slice(encoded[0].length)}`;
  }
  return line;
}

/**
 * Serializes records to CSV text ending with one `eol`.
 *
 * @param {Array<Array<unknown>|Record<string, unknown>>} rows arrays of values;
 *   objects are also accepted when `options.header` is given.
 * @param {{delimiter?: string, eol?: '\r\n'|'\n', header?: string[]}} [options]
 * @returns {string}
 * @throws {TypeError} for invalid rows, values or options.
 */
function stringify(rows, options = {}) {
  if (!Array.isArray(rows)) {
    throw new TypeError(`rows must be an array; received ${describe(rows)}`);
  }
  const { delimiter, eol, header } = readStringifyOptions(options);

  const lines = [];
  if (header !== null) lines.push(encodeRecord(header, delimiter, 'header', true));

  for (let r = 0; r < rows.length; r++) {
    const row = rows[r];
    let values;
    if (Array.isArray(row)) {
      values = row;
    } else if (header !== null && row !== null && typeof row === 'object') {
      values = header.map((name) =>
        Object.prototype.hasOwnProperty.call(row, name) ? row[name] : undefined,
      );
    } else {
      const expected = header === null ? 'an array' : 'an array or an object';
      throw new TypeError(`row ${r} must be ${expected}; received ${describe(row)}`);
    }
    lines.push(encodeRecord(values, delimiter, `row ${r}`, lines.length === 0));
  }

  return lines.length === 0 ? '' : lines.join(eol) + eol;
}

module.exports = { parse, createParser, stringify, CsvError };

'use strict';

const { describe, it } = require('node:test');
const assert = require('node:assert/strict');
const { parse, stringify } = require('../src/csv.js');

// Mulberry32: a small seeded PRNG so random cases are reproducible.
function random(seed) {
  let state = seed >>> 0;
  return () => {
    state = (state + 0x6d2b79f5) >>> 0;
    let t = state;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

describe('stringify: arguments', () => {
  it('rejects rows that are not an array', () => {
    for (const rows of [undefined, null, 'a,b', { 0: ['a'] }]) {
      assert.throws(() => stringify(rows), TypeError);
    }
  });

  it('rejects a record that is not an array when no header is given', () => {
    assert.throws(() => stringify([{ a: 1 }]), TypeError);
    assert.throws(() => stringify([['a'], 'b']), /row 1/);
    assert.throws(() => stringify([null], { header: ['a'] }), TypeError);
  });

  it('rejects invalid delimiter, eol and header options', () => {
    for (const delimiter of ['', ',,', '"', '\r', '\n', 0]) {
      assert.throws(() => stringify([['a']], { delimiter }), TypeError);
    }
    for (const eol of ['\r', '\n\r', '', null]) {
      assert.throws(() => stringify([['a']], { eol }), TypeError);
    }
    for (const header of [true, 'a', [1], [null]]) {
      assert.throws(() => stringify([['a']], { header }), TypeError);
    }
    assert.throws(() => stringify([['a']], null), TypeError);
  });

  it('ignores options it does not know, such as parse skipEmptyLines', () => {
    assert.equal(stringify([['a']], { skipEmptyLines: true }), 'a\r\n');
  });
});

describe('stringify: values', () => {
  it('writes strings, numbers and booleans, and null or undefined as empty', () => {
    assert.equal(
      stringify([['s', 1.5, -0, NaN, true, false, null, undefined]]),
      's,1.5,0,NaN,true,false,,\r\n',
    );
  });

  it('treats holes in a sparse record as empty fields', () => {
    assert.equal(stringify([['a', , 'c']]), 'a,,c\r\n');
  });

  it('rejects every other value type with TypeError naming the position', () => {
    for (const value of [{}, ['x'], Symbol('s'), 10n, () => 1, new Date(0), new String('s')]) {
      assert.throws(() => stringify([['ok', value]]), TypeError);
    }
    assert.throws(() => stringify([['a'], ['b', {}]]), /row 1, field 1/);
  });
});

describe('stringify: quoting', () => {
  it('quotes fields containing the delimiter, a quote, CR or LF, doubling quotes', () => {
    assert.equal(
      stringify([['a,b', 'say "hi"', 'x\ry', 'x\ny', 'plain']]),
      '"a,b","say ""hi""","x\ry","x\ny",plain\r\n',
    );
  });

  it('quotes fields that begin or end with a space, but not inner spaces or tabs', () => {
    assert.equal(stringify([[' a', 'b ', ' ', 'c d', '\te\t']]), '" a","b "," ",c d,\te\t\r\n');
  });

  it('quotes by the configured delimiter only', () => {
    assert.equal(stringify([['a;b', 'c,d']], { delimiter: ';' }), '"a;b";c,d\r\n');
    assert.equal(stringify([['a\tb', 'c']], { delimiter: '\t' }), '"a\tb"\tc\r\n');
  });

  it('writes a record with one empty field as ""', () => {
    assert.equal(stringify([[''], [null], [undefined]]), '""\r\n""\r\n""\r\n');
    assert.equal(stringify([['', '']]), ',\r\n');
  });

  it('quotes a first field that starts with a BOM so parse keeps it', () => {
    assert.equal(stringify([['﻿a', '﻿b']]), '"﻿a",﻿b\r\n');
    assert.equal(stringify([['', 'a']], { delimiter: '﻿' }), '""﻿a\r\n');
  });

  it('writes an empty record as an empty line', () => {
    assert.equal(stringify([[], ['a']]), '\r\na\r\n');
  });
});

describe('stringify: records and eol', () => {
  it('joins records with CRLF by default and ends with one eol', () => {
    assert.equal(stringify([['a', 'b'], ['c', 'd']]), 'a,b\r\nc,d\r\n');
  });

  it('uses \\n when asked', () => {
    assert.equal(stringify([['a'], ['b']], { eol: '\n' }), 'a\nb\n');
  });

  it('returns an empty string for no rows', () => {
    assert.equal(stringify([]), '');
    assert.equal(stringify([], { eol: '\n', delimiter: ';' }), '');
  });

  it('does not change the rows it is given', () => {
    const rows = [['a', 'b'], { x: '1' }];
    const copy = JSON.parse(JSON.stringify(rows));
    stringify(rows, { header: ['x'] });
    assert.deepEqual(rows, copy);
  });
});

describe('stringify: header', () => {
  it('writes the header row, then object values in header order', () => {
    assert.equal(
      stringify([{ b: 2, a: 1 }, { a: 'x,y', b: null }], { header: ['a', 'b'] }),
      'a,b\r\n1,2\r\n"x,y",\r\n',
    );
  });

  it('writes a missing or inherited key as an empty field and ignores extra keys', () => {
    const inherited = Object.create({ a: 'from prototype' });
    assert.equal(
      stringify([{ a: 1, extra: 9 }, inherited, { toString: 'own' }], {
        header: ['a', 'toString'],
      }),
      'a,toString\r\n1,\r\n,\r\n,own\r\n',
    );
  });

  it('accepts array records alongside objects', () => {
    assert.equal(stringify([['1', '2'], { a: '3' }], { header: ['a', 'b'] }), 'a,b\r\n1,2\r\n3,\r\n');
  });

  it('quotes header names like any field', () => {
    assert.equal(stringify([], { header: ['a b ', 'c"d', ''] }), '"a b ","c""d",\r\n');
    assert.equal(stringify([{ '': 'x' }], { header: [''] }), '""\r\nx\r\n');
  });

  it('writes the header row alone when there are no rows', () => {
    assert.equal(stringify([], { header: ['a', 'b'] }), 'a,b\r\n');
  });

  it('treats header: false as no header', () => {
    assert.equal(stringify([['a']], { header: false }), 'a\r\n');
  });
});

describe('stringify then parse', () => {
  const OPTION_SETS = [
    {},
    { skipEmptyLines: true },
    { eol: '\n' },
    { eol: '\n', skipEmptyLines: true, delimiter: ';' },
    { delimiter: '\t' },
    { delimiter: ' ', skipEmptyLines: true },
    { delimiter: '﻿' },
  ];

  function assertRoundTrip(rows, options) {
    const text = stringify(rows, options);
    assert.deepEqual(parse(text, options), rows, `${JSON.stringify(text)} ${JSON.stringify(options)}`);
  }

  it('returns the same rows for hand-picked hard cases', () => {
    const cases = [
      [['']],
      [[''], [''], ['a']],
      [['', ''], ['']],
      [['"'], ['""'], ['"a"']],
      [['a\r\nb', '\r', '\n', '\n\r']],
      [[' '], [' x '], ['\t']],
      [['﻿'], ['﻿a']],
      [['﻿a', 'b']],
      [['', 'a']],
      [['😀', 'é', '\uD800']],
      [[',', ';', '\t', ' ', '﻿']],
    ];
    for (const rows of cases) {
      for (const options of OPTION_SETS) assertRoundTrip(rows, options);
    }
  });

  it('returns the same rows for seeded random rows', () => {
    const next = random(0x4180);
    const alphabet = ['a', 'Z', ',', ';', '\t', ' ', '"', '\r', '\n', '﻿', 'é', '😀', ''];
    for (let run = 0; run < 2000; run++) {
      const rows = [];
      const rowCount = 1 + Math.floor(next() * 4);
      for (let r = 0; r < rowCount; r++) {
        const row = [];
        const fieldCount = 1 + Math.floor(next() * 4);
        for (let f = 0; f < fieldCount; f++) {
          let field = '';
          const length = Math.floor(next() * 5);
          for (let i = 0; i < length; i++) field += alphabet[Math.floor(next() * alphabet.length)];
          row.push(field);
        }
        rows.push(row);
      }
      assertRoundTrip(rows, OPTION_SETS[run % OPTION_SETS.length]);
    }
  });

  it('turns objects written with a header back into the same objects', () => {
    const header = ['name', 'note', '__proto__'];
    // An object literal cannot hold an own __proto__ key, so define each key.
    const own = (values) => {
      const record = {};
      header.forEach((key, i) =>
        Object.defineProperty(record, key, {
          value: values[i],
          enumerable: true,
          writable: true,
          configurable: true,
        }),
      );
      return record;
    };
    const records = [own(['Ada', 'line\nbreak', 'kept']), own([' padded ', '"quoted"', ''])];
    assert.deepEqual(parse(stringify(records, { header }), { header: true }), records);
  });
});

